import statistics
by_bu = {}
for bu, _date, hc in rows:
    by_bu.setdefault(bu, []).append(hc)
cv = {bu: statistics.stdev(v) / statistics.mean(v) for bu, v in by_bu.items()}
ranking = sorted(cv, key=cv.get)
result = {'cv': {k: round(v, 6) for k, v in cv.items()}, 'ranking_most_to_least_stable': ranking}
